k[3,1] = k[1,3]

k[3,2] = k[2,3]

k[3,3] = k[1,1]

k[3,4] = -k[1,2]

k[4,1] = k[1,4]

k[4,2] = k[2,4]

k[4,3] = k[3,4]

k[4,4] = k[2,2]

